import pytest

def prix_ttc(ht: float, taux: float = 0.2) -> float:
    if ht < 0:
        raise ValueError("Prix négatif")
    return round(ht * (1 + taux), 2)

@pytest.mark.parametrize("ht, taux, attendu", [(100, 0.2, 120.0), (10, 0.055, 10.55), (0, 0.2, 0.0)])
def test_prix_ttc(ht, taux, attendu):
    assert prix_ttc(ht, taux) == attendu

def test_prix_negatif():
    with pytest.raises(ValueError):
        prix_ttc(-1)
